mapper.select:
SELECT * FROM tt_task_instance
WHERE definition_id = #{definitionId}
AND lifecycle_category = #{lifecycleCategory}
AND scenario_state = #{scenarioState}
ORDER BY occurrence_at ASC, instance_id ASC
LIMIT #{limit}

mapper.update:
UPDATE tt_task_instance SET
    lifecycle_category = 'TERMINAL',
    scenario_state = #{scenarioState},
    scenario_snapshot_json = #{snapshotJson},
    snapshot_hash = #{snapshotHash},
    terminal_at = #{terminalAt},
    updated_at = #{updatedAt}
WHERE definition_id = #{definitionId}
  AND trigger_binding_id = #{triggerBindingId}
  AND schedule_generation = #{scheduleGeneration}
  AND lifecycle_category = 'WAITING'
